I am trying to parallelize the median filter using the CImg library. The code seems very simple: void omp_median_filter(CImg<float> & img) {
  CImg<float> copy(img);
  size_t i;
  #pragma omp parallel for schedule(dynamic)
  for (i = 1; i < img.width()-1; i++) {
