answers.body:
Your code has multiple bugs. Let's address the silly one first. You write to N+1 elements but only allocate N elements. Change N to 21 and then change for (int i = 0; i <= N; i++) to for (int i = 0; i < N; i++) But your code has another more subtle bug. You're using an induction variable . I don't know an easy way to use induction variables with OpenMP. In your case one easy fix is not use an induction variable and instead do #pragma omp parallel for
for (int i = 0; i < N; i++) {
    int j = i / 2 + 1;
    A[i] = j;
}
cnt = N/2; You can also use a reduction for the final value of cnt but it's redundant and less efficient. #pragma omp parallel for reduction(+:cnt)
for (int i = 0; i < N; i++) {
    if ((i % 2) == 0) cnt++;
    int j = i / 2 + 1;
    A[i] = j;
} If you really want to use an induction variable then you have to do something like this: #pragma omp parallel
{
    int ithread = omp_get_thread_num();
    int nthreads = omp_get_num_threads();
    int start = ithread*N/nthreads;
    int finish = (ithread + 1)*N/nthreads;

    int j = start / 2;
    if (start % 2) j++;
    for (int i = start; i < finish; i++) {
        if ((i % 2) == 0) j++;
        A[i] = j;
    }
}
cnt = N/2; You can also use a reduction for the final value of cnt but as is clear in the code below it's redundant. #pragma omp parallel reduction(+:cnt)
{
    int ithread = omp_get_thread_num();
    int nthreads = omp_get_num_threads();
    int start = ithread*N/nthreads;
    int finish = (ithread + 1)*N/nthreads;

    int j = start / 2;
    if (start % 2) j++;
    for (int i = start; i <finish; i++) {
        if ((i % 2) == 0) {
            j++; cnt++;
        } 
        A[i] = j;
    }
}

