Found a workaround that worked for my case, and thought I'd share it in case someone had a similar problem (unlikely, I know...): Specifying the type of the argument in the lambda function made the compiler understand the code again: #include <iostream>

template <class T>
T add(std::size_t const &maxs) {
  auto step = [&](std::size_t const &maxs) {
    T a = T(0);
#pragma omp declare reduction(MyRed:T                                     \
                              : omp_out += omp_in)                             \
    initializer(omp_priv(omp_orig))
#pragma omp parallel for schedule(dynamic, 10) reduction(MyRed : a)
    for (std::size_t s = 0; s <= maxs; ++s) {
      a += T(1);
    }
    return a;
  };

  return step(maxs);
}

int main() {
  auto a = add<double>(100);

  std::cout << "a=" << a << std::endl;
}

