Since OpenMP 4.0 you can write your own reduction . The idea is : in for loop, you tell the compiler to reduce the place you modify in each loop. since omp doesn't know how to reduce such array, you must write your own adder my_add which will simply sum two array. you tell omp how to use it in your reducer ( myred ) #include <stdio.h>
#include <stdlib.h>

#define LEN 40000

int someCalculations(int i, int j)
{
    return i * j % 40000  ;
}

/* simple adder, just sum x+y in y */
long *my_add(long * x, long *y)
{
    int i;
 #pragma omp parallel for private(i)
    for (i = 0; i < LEN; ++i)
    {
        x[i] += y[i];
    }

    free(y);
    return x;

}

/* reduction declaration:
   name
   type
   operation to be performed
   initializer */
