  return 0;
}



void merge(int low, int mid, int high){

  int p1 = mid - low + 1;
  int p2 = high - mid;

  int *left = malloc(p1 * sizeof(int));
  int *right = malloc(p2 * sizeof(int));

  int i,j,k=low;

  for (i = 0; i < p1; i++){
    left[i] = A[i + low];

    if(greatest==left[i] && found==0){
      found =1;
      findmax[(num-1)]=omp_get_wtime()-start_time;
    }
  }

  for (i = 0; i < p2; i++){
      right[i] = A[i + mid + 1];
      if(greatest==right[i] && found==0){
        found =1;
        findmax[(num-1)]=omp_get_wtime()-start_time;
      }
    }

  i = j = 0;

  while (i < p1 && j < p2) {
    if (left[i] <= right[j])
      A[k++] = left[i++];
    else
      A[k++] = right[j++];
  }

  while (i < p1)
    A[k++] = left[i++];

  while (j < p2)
    A[k++] = right[j++];

  free(left);
  free(right);
}

void merge_sort(int low, int high){

  int mid = low + (high - low) / 2;

  if (low < high) {
    merge_sort(low, mid);

    merge_sort(mid + 1, high);

    merge(low, mid, high);
  }
}

void multi_merge_sort(int low,int high){

  int mid = low + (high - low) / 2;

  if (low < high) {
    merge_sort(low, mid);
    merge_sort(mid + 1, high);
    merge(low, mid, high);
  }
}

