You could try something like the code below. This allocates an array of pointers with a size equal to the number of threads and then each thread allocates private memory i.e. no false sharing. #include <omp.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
  double delta = 20, epsilon = 0;
  double **time_taken; 
  omp_set_dynamic(0);

  #pragma omp parallel
  {
    int it = omp_get_thread_num();
    #pragma omp single
    time_taken = malloc(sizeof *time_taken * omp_get_num_threads());
    time_taken[it] = malloc(sizeof *time_taken[omp_get_thread_num()]);
    *time_taken[it] = 0.0;
  }

  double sum = 0;
  while(delta >= epsilon) {
    #pragma omp parallel
    {
      int it = omp_get_thread_num();
      *time_taken[it] -= omp_get_wtime();
      #pragma omp for reduction(+: sum)
      for(int i= 0 ; i<2000000000; i++) sum += 1.0*i, delta -=1;
      *time_taken[it] += omp_get_wtime();
    }
  }
  printf("sum %f\n", sum);

  #pragma omp parallel
  {
    int it = omp_get_thread_num();
    printf("time taken by thread %d: %f\n", it, *time_taken[it]);
    free(time_taken[omp_get_thread_num()]);
    #pragma omp barrier
    #pragma omp single
    free(time_taken);
  }
}

